  + CompanyName : string
  + Address : string
  + TravelPreferences : string[]
  + ReliabilityRating : float
}

class CreditCard {
  + CardNumber : string
  + ExpiryDate : date
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinimumRating : int
  + MaxCostPerNight : double
  + AdditionalPreferences : string[]
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : double
  + CityArea : string
  + HotelRating : int
  + KeyPreferences : string[]
}

class SpecialOffer {
  + Price : double
}

class Booking {
  + BookingIdentifier : string
  + CancellationDeadline : datetime
  + IsPrepaid : boolean
  + IsConfirmed : boolean
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class RoomType {
  + Type : string
}

class Availability {
  + Period : string
  + IsFullyBooked : boolean
}

Traveller "1" -- "0..*" PreliminaryBooking
Traveller "1" -- "0..*" Booking
Traveller "1" -- "0..*" SpecialOffer
Traveller "1" -- "0..*" CreditCard

PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "0..1" Booking : can become

Booking "0..*" -- "1" Hotel : confirmed by
Booking "0..*" -- "1" Hotel : cancelled by

Hotel "0..*" -- "0..1" HotelChain : run by
Hotel "1" -- "1" City : located in
Hotel "1" -- "0..*" Availability
Availability "1" -- "1" RoomType

Hotel "1" -- "0..*" Booking : manages

@enduml

